#!/usr/bin/env python3
import os
import re
import sys
import io
import zipfile
from dataclasses import dataclass

VERSION_TEXT = """FIGlet Copyright (C) 1991-2012 Glenn Chappell, Ian Chai, John Cowan,
Christiaan Keet and Claudio Matsuoka
Internet: <info@figlet.org> Version: 2.2.5, date: 31 May 2012

FIGlet, along with the various FIGlet fonts and documentation, may be
freely copied and distributed.

If you use FIGlet, please send an e-mail message to <info@figlet.org>.

The latest version of FIGlet is available from the web site,
	http://www.figlet.org/

"""

DEFAULT_FONT_DIR = "/usr/local/share/figlet"
DEFAULT_FONT = "standard"
GERMAN_CODES = [196, 214, 220, 228, 246, 252, 223]
GERMAN_MAP = {ord('['):196, ord('\\'):214, ord(']'):220,
              ord('{'):228, ord('|'):246, ord('}'):252, ord('~'):223}


def basename_prog(argv0: str) -> str:
    b = os.path.basename(argv0)
    return b or argv0


def strip_font_suffix(name: str) -> str:
    low = name.lower()
    for suf in ('.flf', '.tlf', '.flc'):
        if low.endswith(suf):
            return name[:-len(suf)]
    return name


def usage(progbase: str, file):
    print(f"Usage: {progbase} [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]", file=file)
    print("              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]", file=file)
    print("              [ -C controlfile ] [ -I infocode ] [ message ]", file=file)


def print_version(progbase: str):
    sys.stdout.write(VERSION_TEXT)
    usage(progbase, sys.stdout)


def c_atoi(s: str) -> int:
    s = str(s)
    i = 0
    n = len(s)
    while i < n and s[i].isspace():
        i += 1
    sign = 1
    if i < n and s[i] in '+-':
        if s[i] == '-':
            sign = -1
        i += 1
    val = 0
    anydig = False
    while i < n and s[i].isdigit():
        anydig = True
        val = val * 10 + ord(s[i]) - 48
        i += 1
    if not anydig:
        return 0
    return sign * val


@dataclass
class Font:
    name: str
    hardblank: str
    height: int
    old_layout: int
    print_direction: int
    full_layout: int | None
    glyphs: dict


def read_maybe_zip(path: str) -> bytes:
    data = open(path, 'rb').read()
    if zipfile.is_zipfile(io.BytesIO(data)):
        with zipfile.ZipFile(io.BytesIO(data)) as zf:
            for info in zf.infolist():
                if not info.is_dir():
                    return zf.read(info)
    return data


def parse_code_token(tok: str):
    tok = tok.strip()
    if not tok:
        return None
    # strip a trailing comment-ish punctuation only when not part of a number
    try:
        if tok.lower().startswith('-0x'):
            return -int(tok[3:], 16)
        if tok.lower().startswith('0x'):
            return int(tok[2:], 16)
        if re.fullmatch(r'[+-]?\d+', tok):
            return int(tok, 10)
    except Exception:
        return None
    return None


def strip_glyph_line(line: str) -> str:
    if line == '':
        return ''
    end = line[-1]
    s = line[:-1]
    # FIGfonts normally double the endmark on the last row.  Do not eat a
    # whole all-space terminal-font space glyph.
    if end != ' ':
        while s.endswith(end):
            s = s[:-1]
    return s


def pad_rows(rows):
    w = max((len(r) for r in rows), default=0)
    return [r + ' ' * (w - len(r)) for r in rows]


def parse_font(path: str, display_name: str) -> Font:
    data = read_maybe_zip(path)
    text = data.decode('utf-8', 'ignore')
    lines = text.splitlines()
    if not lines or not (lines[0].startswith('flf2a') or lines[0].startswith('tlf2a')):
        raise ValueError('notfig')
    header = lines[0]
    if len(header) < 6:
        raise ValueError('notfig')
    magic = header[:5]
    hardblank = header[5]
    parts = header[6:].strip().split()
    if len(parts) < 5:
        raise ValueError('notfig')
    try:
        height = int(parts[0])
        old_layout = int(parts[3])
        comment_lines = int(parts[4])
        print_direction = int(parts[5]) if len(parts) >= 6 else 0
        full_layout = int(parts[6]) if len(parts) >= 7 else None
    except Exception:
        raise ValueError('notfig')
    idx = 1 + comment_lines
    glyphs = {}

    def read_glyph_at(i):
        rows = []
        for _ in range(height):
            if i >= len(lines):
                rows.append('')
            else:
                rows.append(strip_glyph_line(lines[i]))
            i += 1
        return pad_rows(rows), i

    for code in range(32, 127):
        if idx >= len(lines):
            break
        rows, idx = read_glyph_at(idx)
        glyphs[code] = rows

    # Historical German/Deutsch characters are present in FIGlet .flf fonts.
    if magic == 'flf2a' and idx + height * len(GERMAN_CODES) <= len(lines):
        # If the next line is clearly a code tag and there are not enough fixed
        # glyph rows, this block is skipped by the length check.  Bundled FLF
        # fonts all include these seven glyphs.
        for code in GERMAN_CODES:
            rows, idx = read_glyph_at(idx)
            glyphs[code] = rows

    tag_re = re.compile(r'^\s*((?:-?0x[0-9A-Fa-f]+)|(?:[+-]?\d+))\b')
    while idx < len(lines):
        line = lines[idx]
        m = tag_re.match(line)
        if not m:
            idx += 1
            continue
        code = parse_code_token(m.group(1))
        idx += 1
        if code is None or idx + height > len(lines) + height:  # tolerate EOF padding
            continue
        rows, idx = read_glyph_at(idx)
        glyphs[code] = rows

    return Font(display_name, hardblank, height, old_layout, print_direction, full_layout, glyphs)


def resolve_file(name: str, fontdir: str, kind: str):
    # Returns actual path or None.  kind is 'font' or 'control'.
    low = name.lower()
    if kind == 'font':
        if low.endswith('.flf') or low.endswith('.tlf'):
            variants = [name]
        else:
            variants = [name + '.flf', name + '.tlf', name]
    else:
        if low.endswith('.flc'):
            variants = [name]
        else:
            variants = [name + '.flc', name]

    paths = []
    if '/' in name:
        paths = variants
    else:
        for d in (fontdir, '.'):
            for v in variants:
                paths.append(os.path.join(d, v))
    for p in paths:
        if os.path.isfile(p):
            return p
    return None


class ControlProgram:
    def __init__(self):
        self.commands = []  # list of dicts
        self.utf8 = False

    def add_map(self, mp):
        if mp:
            self.commands.append(mp)

    def translate(self, cp: int) -> int:
        for mp in self.commands:
            if cp in mp:
                cp = mp[cp]
        return cp


def parse_control_atom(tok: str):
    """Return list of codepoints represented by a token/range."""
    tok = tok.strip()
    if tok == '':
        return []

    def one(t):
        if t.startswith('\\'):
            body = t[1:]
            if body.startswith('-'):
                rest = body[1:]
                if rest.lower().startswith('0x'):
                    try: return -int(rest[2:], 16)
                    except Exception: return None
                if rest.isdigit():
                    try: return -int(rest, 10)
                    except Exception: return None
            if body.lower().startswith('0x'):
                try: return int(body[2:], 16)
                except Exception: return None
            if body.isdigit():
                try: return int(body, 10)
                except Exception: return None
            if body:
                return ord(body[0])
            return ord('\\')
        if tok.lower().startswith('-0x'):
            try: return -int(tok[3:], 16)
            except Exception: return None
        if tok.lower().startswith('0x'):
            try: return int(tok[2:], 16)
            except Exception: return None
        if re.fullmatch(r'-?\d+', t):
            try: return int(t, 10)
            except Exception: return None
        return ord(t[0])

    # Find a top-level range separator.  Avoid the sign in \-4 or -0x0004.
    sep = None
    for i, ch in enumerate(tok):
        if ch == '-' and i != 0:
            # If the dash is immediately after a backslash, it is part of \-NN.
            if i > 0 and tok[i-1] == '\\':
                continue
            sep = i
            break
    if sep is not None:
        a = one(tok[:sep])
        b = one(tok[sep+1:])
        if a is None or b is None:
            return []
        step = 1 if b >= a else -1
        return list(range(a, b + step, step))
    v = one(tok)
    return [] if v is None else [v]


def parse_flc_text(text: str, cp: ControlProgram):
    lines = text.splitlines()
    if lines and lines[0].strip().startswith('flc2'):
        for raw in lines[1:]:
            line = raw.strip()
            if not line or line.startswith('#'):
                continue
            if line == 'u' or line.startswith('u '):
                cp.utf8 = True
                continue
            if line.startswith('t') and (len(line) == 1 or line[1].isspace()):
                # A small tr-like command: t FROM TO
                rest = line[1:].strip()
                if not rest:
                    continue
                parts = rest.split()
                if len(parts) < 2:
                    continue
                srcs = parse_control_atom(parts[0])
                dsts = parse_control_atom(parts[1])
                if not srcs or not dsts:
                    continue
                mp = {}
                for i, s in enumerate(srcs):
                    d = dsts[i] if i < len(dsts) else dsts[-1]
                    mp[s] = d
                cp.add_map(mp)
                continue
            # Some table-like FLC files use two tokens without an explicit t.
            parts = line.split()
            if len(parts) >= 2:
                srcs = parse_control_atom(parts[0])
                dsts = parse_control_atom(parts[1])
                if srcs and dsts:
                    mp = {}
                    for i, s in enumerate(srcs):
                        d = dsts[i] if i < len(dsts) else dsts[-1]
                        mp[s] = d
                    cp.add_map(mp)
    else:
        # Unicode mapping table: first two columns are source and destination.
        for raw in lines:
            s = raw.strip()
            if not s or s.startswith('#'):
                continue
            parts = s.split()
            if len(parts) < 2:
                continue
            a = parse_code_token(parts[0])
            b = parse_code_token(parts[1])
            if a is not None and b is not None:
                cp.add_map({a: b})


def load_controls(control_names, fontdir: str, german: bool, progbase: str):
    cp = ControlProgram()
    if german:
        cp.add_map(dict(GERMAN_MAP))
    for name in control_names:
        path = resolve_file(name, fontdir, 'control')
        if path is None:
            print(f"{progbase}: {strip_font_suffix(name)}: Unable to open control file", file=sys.stderr)
            return None
        try:
            data = read_maybe_zip(path)
            text = data.decode('utf-8', 'ignore')
            parse_flc_text(text, cp)
        except Exception:
            # The original is very permissive with malformed control files.
            pass
    return cp


def smush_pair(l: str, r: str, mode: int, hardblank: str):
    if l == ' ':
        return r
    if r == ' ':
        return l
    if l == hardblank or r == hardblank:
        if (mode & 32) and l == hardblank and r == hardblank:
            return hardblank
        if mode == 0:
            return r
        return None
    if (mode & 1) and l == r:
        return l
    if mode & 2:
        us = "|/\\[]{}()<>"
        if l == '_' and r in us:
            return r
        if r == '_' and l in us:
            return l
    if mode & 4:
        classes = ["|", "/\\", "[]", "{}", "()", "<>"]
        li = ri = None
        for i, cls in enumerate(classes):
            if l in cls:
                li = i
            if r in cls:
                ri = i
        if li is not None and ri is not None and li != ri:
            return r if ri > li else l
    if mode & 8:
        if (l, r) in [('[', ']'), ('{', '}'), ('(', ')')]:
            return '|'
    if mode & 16:
        if l == '/' and r == '\\':
            return '|'
        if l == '\\' and r == '/':
            return 'Y'
        if l == '>' and r == '<':
            return 'X'
    if mode == 0:
        return r
    return None


def can_overlap(rows, glyph, amt: int, layout: str, mode: int, hardblank: str):
    if amt == 0:
        return True
    curw = len(rows[0]) if rows else 0
    gw = len(glyph[0]) if glyph else 0
    allow_collision = layout == 'smush' and gw > 1
    for a, b in zip(rows, glyph):
        for k in range(amt):
            l = a[curw - amt + k]
            r = b[k]
            if l != ' ' and r != ' ':
                if not allow_collision:
                    return False
                if smush_pair(l, r, mode, hardblank) is None:
                    return False
    return True


def merge_rows(rows, glyph, amt: int, layout: str, mode: int, hardblank: str):
    if amt == 0:
        return [a + b for a, b in zip(rows, glyph)]
    curw = len(rows[0])
    out = []
    for a, b in zip(rows, glyph):
        prefix = a[:curw - amt]
        mid = []
        for k in range(amt):
            l = a[curw - amt + k]
            r = b[k]
            if l == ' ':
                mid.append(r)
            elif r == ' ':
                mid.append(l)
            else:
                m = smush_pair(l, r, mode, hardblank)
                mid.append(m if m is not None else r)
        out.append(prefix + ''.join(mid) + b[amt:])
    return out


def leading_spaces(row: str) -> int:
    i = 0
    while i < len(row) and row[i] == ' ':
        i += 1
    return i


def append_glyph(rows, glyph, layout: str, mode: int, hardblank: str, trim_initial: bool):
    glyph = [r for r in glyph]
    if rows is None:
        if layout != 'full' and trim_initial and glyph:
            amt = min(leading_spaces(r) for r in glyph)
            if amt:
                glyph = [r[amt:] for r in glyph]
        return glyph
    if not rows:
        return glyph
    if layout == 'full':
        amt = 0
    else:
        max_amt = min(len(rows[0]), len(glyph[0]) if glyph else 0)
        amt = 0
        for a in range(max_amt, -1, -1):
            if can_overlap(rows, glyph, a, layout, mode, hardblank):
                amt = a
                break
    return merge_rows(rows, glyph, amt, layout, mode, hardblank)


def default_layout(font: Font):
    fl = font.full_layout
    if fl is not None:
        if fl & 128:
            return 'smush', fl & 63
        if fl & 64:
            return 'kern', 0
        return 'full', 0
    old = font.old_layout
    if old < 0:
        return 'full', 0
    if old == 0:
        return 'kern', 0
    return 'smush', old & 63


def forced_smush_layout(font: Font):
    mode = 0
    if font.full_layout is not None:
        mode = font.full_layout & 63
    if mode == 0 and font.old_layout > 0:
        mode = font.old_layout & 63
    return 'smush', mode


def choose_layout(font: Font, layout_setting):
    if layout_setting is None or layout_setting == 'default':
        return default_layout(font)
    if layout_setting == 'force_smush':
        return forced_smush_layout(font)
    if layout_setting == 'kern':
        return 'kern', 0
    if layout_setting == 'full':
        return 'full', 0
    if layout_setting == 'overlap':
        return 'smush', 0
    if isinstance(layout_setting, tuple) and layout_setting[0] == 'mode':
        return 'smush', layout_setting[1] & 63
    return default_layout(font)


def rows_width(rows):
    return len(rows[0]) if rows else 0


def render_codes_no_wrap(codes, font: Font, layout, mode, trim_initial=True):
    rows = None
    had_input = False
    for cp in codes:
        had_input = True
        glyph = font.glyphs.get(cp)
        if glyph is None:
            continue
        rows = append_glyph(rows, glyph, layout, mode, font.hardblank, trim_initial if rows is None else True)
    if rows is None:
        if had_input:
            return ['' for _ in range(font.height)]
        return None
    return rows


def tokenize_spaces(codes):
    tokens = []
    i = 0
    n = len(codes)
    while i < n:
        is_space = codes[i] == 32
        j = i + 1
        while j < n and (codes[j] == 32) == is_space:
            j += 1
        tokens.append((is_space, codes[i:j]))
        i = j
    return tokens


def append_sequence(rows, seq, font, layout, mode, trim_initial):
    out = rows
    for cp in seq:
        glyph = font.glyphs.get(cp)
        if glyph is None:
            continue
        out = append_glyph(out, glyph, layout, mode, font.hardblank, trim_initial if out is None else True)
    return out


def char_wrap_word(word, font, layout, mode, limit, trim_initial):
    blocks = []
    rows = None
    for cp in word:
        glyph = font.glyphs.get(cp)
        if glyph is None:
            # missing char still makes an empty figline if the word has only missing chars
            continue
        cand = append_glyph(rows, glyph, layout, mode, font.hardblank, trim_initial if rows is None else True)
        if rows is not None and limit >= 0 and rows_width(cand) > limit:
            blocks.append(rows)
            rows = append_glyph(None, glyph, layout, mode, font.hardblank, trim_initial)
        else:
            rows = cand
    if rows is not None:
        blocks.append(rows)
    elif word:
        blocks.append(['' for _ in range(font.height)])
    return blocks


def render_codes_wrapped(codes, font: Font, layout, mode, width: int, trim_initial=True):
    # Width and justification in FIGlet effectively use outputwidth-1 columns.
    if width == 1:
        blocks = []
        nonspace = [c for c in codes if c != 32]
        if nonspace:
            for cp in nonspace:
                glyph = font.glyphs.get(cp)
                if glyph is None:
                    blocks.append(['' for _ in range(font.height)])
                else:
                    blocks.append([r for r in glyph])
            return blocks
        else:
            rows = render_codes_no_wrap(codes, font, 'full', 0, trim_initial=False)
            return [] if rows is None else [rows]

    limit = width - 1 if width > 0 else 10**9
    tokens = tokenize_spaces(codes)
    blocks = []
    current = None
    pending_spaces = []
    had_any = False

    for is_space, seq in tokens:
        had_any = True
        if is_space:
            pending_spaces.extend(seq)
            continue
        # Non-space word.  Try adding pending spaces plus this word.
        if current is None:
            combined = pending_spaces + seq
            pending_spaces = []
            # If the first line itself is too long, wrap by character.
            cand = append_sequence(None, combined, font, layout, mode, trim_initial)
            if cand is not None and rows_width(cand) > limit and len(seq) > 1:
                # Preserve leading spaces with first character; then char-wrap the rest.
                blocks2 = char_wrap_word(combined, font, layout, mode, limit, trim_initial)
                if blocks2:
                    blocks.extend(blocks2[:-1])
                    current = blocks2[-1]
                else:
                    current = None
            else:
                current = cand
        else:
            cand = append_sequence(current, pending_spaces + seq, font, layout, mode, trim_initial)
            if cand is not None and rows_width(cand) > limit:
                blocks.append(current)
                pending_spaces = []  # discard spaces at the break
                # Now place/wrap the word on the new line.
                cand2 = append_sequence(None, seq, font, layout, mode, trim_initial)
                if cand2 is not None and rows_width(cand2) > limit and len(seq) > 1:
                    blocks2 = char_wrap_word(seq, font, layout, mode, limit, trim_initial)
                    if blocks2:
                        blocks.extend(blocks2[:-1])
                        current = blocks2[-1]
                    else:
                        current = None
                else:
                    current = cand2
            else:
                current = cand
                pending_spaces = []

    if pending_spaces:
        if current is None:
            current = append_sequence(None, pending_spaces, font, layout, mode, trim_initial)
        else:
            cand = append_sequence(current, pending_spaces, font, layout, mode, trim_initial)
            if cand is not None and rows_width(cand) > limit:
                blocks.append(current)
                current = None  # trailing spaces at wrapped EOL are discarded
            else:
                current = cand

    if current is not None:
        blocks.append(current)
    elif had_any:
        blocks.append(['' for _ in range(font.height)])
    return blocks


def finalize_and_justify(rows, font: Font, justification: str, direction: int, width: int):
    target = width - 1 if width > 0 else 0
    out = []
    for r in rows:
        s = r.replace(font.hardblank, ' ')
        just = justification
        if just == 'auto':
            just = 'right' if direction == 1 else 'left'
        if just == 'right' and target > len(s):
            s = ' ' * (target - len(s)) + s
        elif just == 'center' and target > len(s):
            s = ' ' * ((target - len(s)) // 2) + s
        out.append(s)
    return out


def bytes_to_code_lines(data: bytes, cp: ControlProgram, paragraph: bool):
    if paragraph and data:
        b = bytearray()
        n = len(data)
        for i, ch in enumerate(data):
            if ch == 10:  # newline
                prev_nl = (i > 0 and data[i-1] == 10)
                next_space = (i + 1 < n and data[i+1] in (32, 9))
                if (not prev_nl) and (not next_space):
                    b.append(32)
                else:
                    b.append(ch)
            else:
                b.append(ch)
        data = bytes(b)
    if cp.utf8:
        cps = [ord(ch) for ch in data.decode('utf-8', 'ignore')]
    else:
        cps = list(data)
    lines = []
    cur = []
    saw_any = False
    for c in cps:
        saw_any = True
        c = cp.translate(c)
        if c == 9:
            c = 32
        if c in (10, 13, 12):
            lines.append(cur)
            cur = []
        elif c < 32 or c == 127:
            # Other C0 controls are ignored.
            continue
        else:
            cur.append(c)
    if cur or (saw_any and (len(cps) > 0 and cps[-1] not in (10, 13, 12))):
        lines.append(cur)
    return lines


def assemble_message_bytes(operands):
    if not operands:
        return None
    data = bytearray()
    prev_nonempty = False
    n = len(operands)
    for i, op in enumerate(operands):
        b = os.fsencode(op)
        if b == b'':
            if i != n - 1:
                data.append(10)
            prev_nonempty = False
        else:
            if prev_nonempty:
                data.append(32)
            data.extend(b)
            prev_nonempty = True
    return bytes(data)


class Options:
    def __init__(self):
        self.font = DEFAULT_FONT
        self.fontdir = DEFAULT_FONT_DIR
        self.width = 80
        self.paragraph = False
        self.justification = 'auto'
        self.direction = 'font'  # font, ltr, rtl
        self.layout = None
        self.info = -1
        self.controls = []
        self.german = False


def parse_args(argv):
    opts = Options()
    operands = []
    prog0 = argv[0]
    progbase = basename_prog(prog0)
    opt_requires = set('dfmwCI')
    valid_noarg = set('cklnoprstvxDELNRSWXS')
    # Note: -S is included separately; the set above includes S.
    args = argv[1:]
    i = 0
    end_options = False
    while i < len(args):
        arg = args[i]
        if end_options:
            operands.append(arg)
            i += 1
            continue
        if arg == '--':
            end_options = True
            i += 1
            continue
        if arg != '-' and arg.startswith('-') and len(arg) > 1:
            j = 1
            while j < len(arg):
                ch = arg[j]
                if ch in opt_requires:
                    if j + 1 < len(arg):
                        val = arg[j+1:]
                        j = len(arg)
                    else:
                        if i + 1 >= len(args):
                            print(f"{prog0}: option requires an argument -- '{ch}'", file=sys.stderr)
                            usage(progbase, sys.stderr)
                            return None, None, 1
                        i += 1
                        val = args[i]
                        j = len(arg)
                    if ch == 'd':
                        opts.fontdir = val
                    elif ch == 'f':
                        opts.font = val
                    elif ch == 'w':
                        n = c_atoi(val)
                        if n > 0:
                            opts.width = n
                    elif ch == 'm':
                        n = c_atoi(val)
                        if n == 0:
                            opts.layout = 'kern'
                        elif n == -1:
                            opts.layout = 'full'
                        elif n == -2:
                            opts.layout = 'default'
                        else:
                            opts.layout = ('mode', n)
                    elif ch == 'C':
                        opts.controls.append(val)
                    elif ch == 'I':
                        opts.info = c_atoi(val)
                    break
                elif ch in valid_noarg:
                    if ch == 'c':
                        opts.justification = 'center'
                    elif ch == 'l':
                        opts.justification = 'left'
                    elif ch == 'r':
                        opts.justification = 'right'
                    elif ch == 'x':
                        opts.justification = 'auto'
                    elif ch == 't':
                        try:
                            cols = os.get_terminal_size(sys.stdout.fileno()).columns
                            if cols > 0:
                                opts.width = cols
                        except Exception:
                            pass
                    elif ch == 'p':
                        opts.paragraph = True
                    elif ch == 'n':
                        opts.paragraph = False
                    elif ch == 'D':
                        opts.german = True
                    elif ch == 'E':
                        opts.german = False
                    elif ch == 'N':
                        opts.controls.clear()
                    elif ch == 's':
                        opts.layout = 'default'
                    elif ch == 'S':
                        opts.layout = 'force_smush'
                    elif ch == 'k':
                        opts.layout = 'kern'
                    elif ch == 'W':
                        opts.layout = 'full'
                    elif ch == 'o':
                        opts.layout = 'overlap'
                    elif ch == 'v':
                        opts.info = 0
                    elif ch == 'L':
                        opts.direction = 'ltr'
                    elif ch == 'R':
                        opts.direction = 'rtl'
                    elif ch == 'X':
                        opts.direction = 'font'
                    # other valid chars handled above
                    j += 1
                else:
                    print(f"{prog0}: invalid option -- '{ch}'", file=sys.stderr)
                    usage(progbase, sys.stderr)
                    return None, None, 1
            i += 1
        else:
            operands.append(arg)
            i += 1
    return opts, operands, 0


def main(argv=None):
    if argv is None:
        argv = sys.argv
    opts, operands, rc = parse_args(argv)
    progbase = basename_prog(argv[0])
    if rc != 0:
        return rc

    if opts.info >= 0:
        if opts.info == 0:
            print_version(progbase)
        elif opts.info == 1:
            print("20205")
        elif opts.info == 2:
            print(opts.fontdir)
        elif opts.info == 3:
            print(strip_font_suffix(opts.font))
        elif opts.info == 4:
            print(opts.width)
        elif opts.info == 5:
            print("flf2 tlf2")
        return 0

    cp = load_controls(opts.controls, opts.fontdir, opts.german, progbase)
    if cp is None:
        return 1

    font_display = strip_font_suffix(opts.font)
    font_path = resolve_file(opts.font, opts.fontdir, 'font')
    if font_path is None:
        print(f"{progbase}: {font_display}: Unable to open font file", file=sys.stderr)
        return 1
    try:
        font = parse_font(font_path, font_display)
    except ValueError:
        print(f"{progbase}: {font_display}: Not a FIGlet 2 font file", file=sys.stderr)
        return 1
    except Exception:
        print(f"{progbase}: {font_display}: Unable to open font file", file=sys.stderr)
        return 1

    direction = font.print_direction
    if opts.direction == 'ltr':
        direction = 0
    elif opts.direction == 'rtl':
        direction = 1

    layout, smode = choose_layout(font, opts.layout)

    msg = assemble_message_bytes(operands)
    if msg is None:
        msg = sys.stdin.buffer.read()
    if not msg:
        return 0

    code_lines = bytes_to_code_lines(msg, cp, opts.paragraph)
    all_output = []
    for codes in code_lines:
        if direction == 1:
            codes = list(reversed(codes))
        trim_initial = (direction == 0)
        blocks = render_codes_wrapped(codes, font, layout, smode, opts.width, trim_initial=trim_initial)
        for rows in blocks:
            all_output.extend(finalize_and_justify(rows, font, opts.justification, direction, opts.width))

    if all_output:
        sys.stdout.buffer.write(('\n'.join(all_output) + '\n').encode('utf-8'))
    return 0


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except BrokenPipeError:
        raise SystemExit(1)
